from collections import Counter

def solve(grid):
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0])

    # Find horizontal line (uniform row)
    h = -1
    line_val = None
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            h = i
            line_val = row[0]
            break

    # Find vertical line (column consisting entirely of line_val)
    v = -1
    for j in range(cols):
        if all(grid[i][j] == line_val for i in range(rows)):
            v = j
            break

    # Determine background color (most common value excluding line_val)
    non_line_values = [grid[i][j] for i in range(rows) for j in range(cols) if grid[i][j] != line_val]
    if not non_line_values:
        return []

    counter = Counter(non_line_values)
    background = counter.most_common(1)[0][0]

    # Find the marker position (element that is neither line_val nor background)
    marker_i, marker_j = -1, -1
    found = False
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != line_val and grid[i][j] != background:
                marker_i, marker_j = i, j
                found = True
                break
        if found:
            break

    if not found:
        return []

    # Determine quadrant bounds based on marker position relative to cross
    if marker_i < h:
        row_start, row_end = 0, h
    else:
        row_start, row_end = h + 1, rows

    if marker_j < v:
        col_start, col_end = 0, v
    else:
        col_start, col_end = v + 1, cols

    # Extract the quadrant
    result = [row[col_start:col_end] for row in grid[row_start:row_end]]
    return result
